  async function scanExpenseFile(file=state.aiFile){
    if(state.aiScanning||!file)return;
    if(!AI_FILE_TYPES.has(file.type)){aiStatus('Unsupported file','Please upload a JPG, PNG, WEBP or PDF.','error');return}
    if(file.size>10*1024*1024){aiStatus('File too large','This file is too large. Please choose a smaller file.','error');return}
    const sb=client();if(!sb){aiStatus('AI unavailable','AI scanning is temporarily unavailable. You can still enter the expense manually.','error');return}
    state.aiScanning=true;state.aiFile=file;renderAiPreview(file);aiStatus('Scanning with AI…','Reading supplier, dates, GST, total and category.','loading');
    if($('expTakePhoto'))$('expTakePhoto').disabled=true;if($('expUploadDoc'))$('expUploadDoc').disabled=true;
    try{
      const optimised=await optimiseImage(file),base64=await fileToBase64(optimised);
      const {data,error}=await sb.functions.invoke('scan-expense-document',{body:{filename:file.name,mime_type:optimised.type||file.type,file_base64:base64,business_id:business()?.id}});
      if(error)throw error;
      if(!data?.ok)throw new Error(data?.error||'AI scan failed');
      // A scan may create a previously unknown supplier on the server. Refresh only
      // the reference lists before applying the result so the new supplier/category
      // can be selected immediately in the existing dropdowns.
      if((data.result?.matched_supplier_id&&!state.suppliers.some(s=>s.id===data.result.matched_supplier_id))||(data.result?.matched_category_id&&!state.categories.some(c=>c.id===data.result.matched_category_id)))await loadReferenceData();
      applyAiResult(data.result);
    }catch(e){
      console.error(e);
      const msg=String(e?.message||e||'');
      aiStatus('We couldn’t read this document.',msg.includes('OPENAI_API_KEY')||msg.includes('temporarily')?'AI scanning is temporarily unavailable. You can still enter the expense manually.':'You can try another image or enter the expense manually.','error');
    }finally{
      state.aiScanning=false;if($('expTakePhoto'))$('expTakePhoto').disabled=false;if($('expUploadDoc'))$('expUploadDoc').disabled=false;if($('expAiRescan'))$('expAiRescan').hidden=!state.aiFile;
    }
  }
