  function expenseListDates(){
    const preset=$('expenseListRange')?.value||'this_month',now=new Date(),end=today();let start='';
    if(preset==='this_month')start=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
    else if(preset==='last_month'){const a=new Date(now.getFullYear(),now.getMonth()-1,1),b=new Date(now.getFullYear(),now.getMonth(),0);start=`${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,'0')}-01`;return{start,end:`${b.getFullYear()}-${String(b.getMonth()+1).padStart(2,'0')}-${String(b.getDate()).padStart(2,'0')}`}}
    else if(preset==='3')start=addDays(end,-90);else if(preset==='6')start=addDays(end,-183);else if(preset==='12')start=addDays(end,-365);
    else return{start:$('expenseFrom')?.value||'',end:$('expenseTo')?.value||''};
    return{start,end};
  }
