  async function openSupplierRefundFor(creditId){const credit=state.supplierCredits.find(x=>String(x.id)===String(creditId));if(!credit||credit.lifecycle_state!=='recorded')return toast('Recorded supplier credit not found.');const r=await client().rpc('v6170c45_supplier_credit_available_for_credit',{p_supplier_credit_id:creditId});if(r.error)return toast(r.error.message);const available=num(r.data);if(available<=0.005)return toast('There is no supplier credit currently available for refund.');$('supplierRefundCreditId').value=creditId;$('supplierRefundSupplierId').value=credit.supplier_id;$('supplierRefundSupplier').textContent=`${supplierName(credit.supplier_id)} · ${credit.credit_note_number||'Supplier credit'}`;$('supplierRefundAvailable').textContent=money(available);$('supplierRefundAmount').value=available.toFixed(2);$('supplierRefundAmount').max=available.toFixed(2);$('supplierRefundDate').value=today();$('supplierRefundMethod').value='bank_transfer';$('supplierRefundReference').value='';$('supplierRefundNotes').value='';$('supplierRefundModal').classList.add('open')}
  async function saveSupplierRefund(){const creditId=$('supplierRefundCreditId').value,amount=num($('supplierRefundAmount').value),bid=business()?.id;if(amount<=0)return toast('Enter a refund amount.');const c=await client().rpc('v6170c45_create_supplier_refund_for_credit',{p_supplier_credit_id:creditId,p_amount:amount,p_refund_date:$('supplierRefundDate').value,p_method:$('supplierRefundMethod').value,p_reference:$('supplierRefundReference').value.trim()||null,p_notes:$('supplierRefundNotes').value.trim()||null,p_idempotency_key:crypto.randomUUID()});if(c.error)return toast(c.error.message);const r=await client().rpc('v6170c45_record_supplier_refund',{p_refund_id:c.data.id});if(r.error)return toast(r.error.message);if(business()?.id!==bid)return;$('supplierRefundModal').classList.remove('open');await loadExpenses();renderSupplierCorrections();toast('Supplier refund recorded')}
  async function voidSupplierRefund(id){const reason=prompt('Reason for voiding this supplier refund:');if(!reason?.trim())return;const r=await client().rpc('v6170c45_void_supplier_refund',{p_refund_id:id,p_reason:reason.trim()});if(r.error)return toast(r.error.message);await loadExpenses();renderSupplierCorrections();toast('Supplier refund voided')}
  function openSupplierCredit(id){$('supplierCreditEditId').value='';const e=state.expenses.find(x=>x.id===id);if(!e||!isRecordedExpense(e))return;const remaining=supplierCreditRemaining(e);if(remaining<=0.005)return toast('This expense is already fully credited.');$('supplierCreditExpenseId').value=e.id;$('supplierCreditTitle').textContent='Add Supplier Credit';$('supplierCreditExpense').textContent=`${e.expense_number} · ${e.supplier_name||'Supplier'}`;$('supplierCreditAvailable').textContent=money(remaining);$('supplierCreditType').value='partial';$('supplierCreditAmount').value=remaining.toFixed(2);$('supplierCreditDate').value=today();$('supplierCreditReference').value='';$('supplierCreditReason').value='';$('supplierCreditModal').classList.add('open')}
  async function saveSupplierCredit(recordNow=true){const e=state.expenses.find(x=>x.id===$('supplierCreditExpenseId').value);if(!e)return;const amount=num($('supplierCreditAmount').value),remaining=supplierCreditRemaining(e);if(amount<=0||amount>remaining+0.005)return toast('Credit amount must be within the available expense amount.');const bid=business()?.id,editId=$('supplierCreditEditId').value;const res=editId?await client().rpc('v6170c45_update_supplier_credit',{p_credit_id:editId,p_total:amount,p_credit_date:$('supplierCreditDate').value,p_supplier_reference:$('supplierCreditReference').value.trim()||null,p_reason:$('supplierCreditReason').value.trim()||null,p_credit_type:$('supplierCreditType').value}):await client().rpc('v6170c45_create_supplier_credit',{p_expense_id:e.id,p_credit_type:$('supplierCreditType').value,p_total:amount,p_credit_date:$('supplierCreditDate').value,p_supplier_reference:$('supplierCreditReference').value.trim()||null,p_reason:$('supplierCreditReason').value.trim()||null,p_idempotency_key:crypto.randomUUID()});if(res.error)return toast(res.error.message);if(recordNow){const rr=await client().rpc('v6170c45_record_supplier_credit',{p_credit_id:res.data.id});if(rr.error)return toast(rr.error.message)}if(business()?.id!==bid)return;$('supplierCreditModal').classList.remove('open');await loadExpenses();renderBills();toast(recordNow?'Supplier credit recorded':'Supplier credit saved as draft')}
  async function voidExpense(id){const e=state.expenses.find(x=>x.id===id);if(!e||!isRecordedExpense(e))return;const reason=prompt('Reason for voiding this recorded expense:');if(!reason?.trim())return;const bid=business()?.id;const r=await client().rpc('v6170c45_void_expense',{p_expense_id:id,p_reason:reason.trim()});if(r.error)return toast(r.error.message);if(business()?.id!==bid)return;await loadExpenses();renderBills();toast('Expense voided with audit history preserved')}
  function bindBillActions(){const root=$('expenseRows');root.querySelectorAll('[data-exp-view]').forEach(b=>b.onclick=()=>viewExpense(b.dataset.expView));root.querySelectorAll('[data-exp-edit]').forEach(b=>b.onclick=()=>editExpense(b.dataset.expEdit));root.querySelectorAll('[data-exp-pay]').forEach(b=>b.onclick=()=>openPayment(b.dataset.expPay));root.querySelectorAll('[data-exp-rec]').forEach(b=>b.onclick=()=>toggleReconcile(b.dataset.expRec));root.querySelectorAll('[data-exp-dup]').forEach(b=>b.onclick=()=>duplicateExpense(b.dataset.expDup));root.querySelectorAll('[data-exp-archive]').forEach(b=>b.onclick=()=>archiveExpense(b.dataset.expArchive));root.querySelectorAll('[data-exp-credit]').forEach(b=>b.onclick=()=>openSupplierCredit(b.dataset.expCredit));root.querySelectorAll('[data-exp-void]').forEach(b=>b.onclick=()=>voidExpense(b.dataset.expVoid));root.querySelectorAll('[data-exp-file]').forEach(b=>{const e=state.expenses.find(x=>x.id===b.dataset.expFile),a=e?.expense_attachments?.[0];b.onclick=()=>openAttachment(a)})}
  async function viewExpense(id){let e=state.expenses.find(x=>x.id===id);if(!e){await loadExpenses();e=state.expenses.find(x=>x.id===id)}if(!e)return;const cats=new Map(state.categories.map(c=>[c.id,c.name])),jobs=new Map(state.jobs.map(j=>[j.id,`${j.costing_number} · ${j.job_description||j.customer_name}`]));const lines=e.is_split?(e.expense_lines||[]).map(l=>`<tr><td>${esc(l.description||'')}</td><td>${esc(cats.get(l.category_id)||'—')}</td><td>${esc(jobs.get(l.job_costing_id)||'—')}</td><td>${money(l.ex_gst)}</td><td>${money(l.gst_amount)}</td><td>${money(l.total_amount)}</td></tr>`).join(''):'';const pays=(e.expense_payments||[]).map(p=>`<tr><td>${esc(p.payment_date)}</td><td>${money(p.amount)}</td><td>${esc(p.payment_method||'—')}</td><td>${esc(p.reference||'')}</td><td>${reconcileBadge(p.reconciled)}</td></tr>`).join('')||'<tr><td colspan="5">No payments recorded.</td></tr>';$('expenseDetailContent').innerHTML=`<div class="expense-detail-head"><div><h2>${esc(e.expense_number)}</h2><p>${esc(e.supplier_name||'Supplier')}</p></div>${badge(statusOf(e))}</div><div class="expense-detail-grid"><div><span>Supplier reference</span><strong>${esc(e.supplier_reference||'—')}</strong></div><div><span>Invoice / receipt date</span><strong>${esc(e.invoice_date)}</strong></div><div><span>Due date</span><strong>${esc(e.due_date||'—')}</strong></div><div><span>Category</span><strong>${esc(e.is_split?'Split expense':cats.get(e.category_id)||'—')}</strong></div><div><span>Linked job</span><strong>${esc(e.is_split?'See split lines':jobs.get(e.job_costing_id)||'—')}</strong></div><div><span>Reconciliation</span><strong>${e.reconciled?'Reconciled':'Unreconciled'}</strong></div><div><span>Ex GST</span><strong>${money(e.ex_gst)}</strong></div><div><span>GST</span><strong>${money(e.gst_amount)}</strong></div><div><span>Total</span><strong>${money(e.total_amount)}</strong></div><div><span>Amount paid</span><strong>${money(e.amount_paid)}</strong></div><div><span>Supplier credits</span><strong>${money(recordedSupplierCreditTotal(e))}</strong></div><div><span>Remaining obligation</span><strong>${money(supplierCreditAdjustedOutstanding(e))}</strong></div></div>${num(e.business_use_percent??100)<99.995?`<div class="expense-allocation-detail"><h3>Business-use allocation</h3><div class="expense-detail-grid"><div><span>Original bill</span><strong>${money(e.total_amount)}</strong></div><div><span>Business use</span><strong>${Number(num(e.business_use_percent).toFixed(2))}%</strong></div><div><span>Business portion</span><strong>${money(e.business_use_amount)}</strong></div><div><span>Private / non-business</span><strong>${money(e.private_use_amount)}</strong></div><div><span>Business GST</span><strong>${money(e.business_gst_amount)}</strong></div><div><span>Allocation basis</span><strong>${esc(String(e.allocation_basis||'—').replaceAll('_',' '))}</strong></div></div>${e.allocation_notes?`<p class="hint">${esc(e.allocation_notes)}</p>`:''}</div>`:''}${e.description?`<div class="expense-notes"><strong>Description / notes</strong><p>${esc(e.description)}</p></div>`:''}${e.is_split?`<h3>Expense split</h3><div class="table-scroll"><table><thead><tr><th>Description</th><th>Category</th><th>Job</th><th>Ex GST</th><th>GST</th><th>Total</th></tr></thead><tbody>${lines}</tbody></table></div>`:''}<h3>Supporting documents</h3><div class="expense-detail-files">${(e.expense_attachments||[]).map(a=>`<button class="secondary" data-detail-file="${a.id}">${esc(a.original_filename)}</button>`).join('')||'<span class="hint">No attachment.</span>'}</div><h3>Payment history</h3><div class="table-scroll"><table><thead><tr><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Reconciliation</th></tr></thead><tbody>${pays}</tbody></table></div><p class="hint">Created ${new Date(e.created_at).toLocaleString()} · Last updated ${new Date(e.updated_at).toLocaleString()}</p><div class="actions">${isVoidedExpense(e)?'<span class="c1-protected-action">Voided bill retained for audit. No payment or payable remains.</span>':isRecordedExpense(e)?'<span class="c1-protected-action">Recorded expenses can still be viewed, paid and reconciled. Financial changes need a correction.</span>':'<button class="secondary" id="detailEditExpense">Edit</button>'}${!isVoidedExpense(e)&&supplierCreditAdjustedOutstanding(e)>0.005&&e.payment_status!=='draft'?'<button class="primary" id="detailRecordPayment">Record Payment</button>':''}${isVoidedExpense(e)?'':`<button class="secondary" id="detailToggleReconcile">${e.reconciled?'Mark Unreconciled':'Mark Reconciled'}</button>`}</div>`;$('expenseDetailModal').classList.add('open');$('expenseDetailContent').querySelectorAll('[data-detail-file]').forEach(b=>b.onclick=()=>openAttachment((e.expense_attachments||[]).find(a=>a.id===b.dataset.detailFile)));if($('detailEditExpense'))$('detailEditExpense').onclick=()=>{$('expenseDetailModal').classList.remove('open');editExpense(e.id)};if($('detailRecordPayment'))$('detailRecordPayment').onclick=()=>{$('expenseDetailModal').classList.remove('open');openPayment(e.id)};if($('detailToggleReconcile'))$('detailToggleReconcile').onclick=async()=>{$('expenseDetailModal').classList.remove('open');await toggleReconcile(e.id)}}
  async function editExpense(id){const e=state.expenses.find(x=>x.id===id);if(!e)return;if(isVoidedExpense(e))return toast('Voided bills are retained for audit and cannot be edited.');if(isRecordedExpense(e))return recordedExpenseGuidance();state.editingId=id;state.pendingFiles=[];state.attachments=e.expense_attachments||[];state.split=!!e.is_split;state.splitLines=(e.expense_lines||[]).sort((a,b)=>a.sort_order-b.sort_order).map(l=>({description:l.description||'',category_id:l.category_id||'',job_costing_id:l.job_costing_id||'',amount:l.total_amount,gst_treatment:l.gst_treatment,gst_rate:l.gst_rate}));fillPickers();$('expNumber').value=e.expense_number;$('expSupplier').value=e.supplier_id||'';$('expReference').value=e.supplier_reference||'';$('expInvoiceDate').value=e.invoice_date||today();$('expDueDate').value=e.due_date||'';$('expDescription').value=e.description||'';$('expCategory').value=e.category_id||'';$('expJob').value=e.job_costing_id||'';$('expAmountType').value=e.amount_type||'inclusive';$('expGstTreatment').value=e.gst_treatment||'gst';resetAuTax();renderAuTax();if($('expAuTaxClass'))$('expAuTaxClass').value=e.au_tax_classification||'';$('expAmount').value=e.amount_type==='exclusive'?num(e.ex_gst):num(e.total_amount);$('expGstOverride').checked=!!e.gst_override;$('expGstAmount').readOnly=!e.gst_override;$('expGstAmount').value=num(e.gst_amount).toFixed(2);$('expExGst').value=num(e.ex_gst).toFixed(2);$('expTotalCalculated').value=num(e.total_amount).toFixed(2);$('expPaymentStatus').value=e.payment_status==='draft'?'draft':(e.payment_status==='paid'?'paid':'unpaid');$('expPaymentStatus').disabled=false;$('expSplitArea').hidden=!state.split;$('expSplitToggle').textContent=state.split?'Use Single Category':'+ Split Expense';const pct=e.business_use_percent==null?100:num(e.business_use_percent),partial=pct<99.995;$('expBusinessUseMode').value=partial?'partial':'full';$('expBusinessUsePercent').value=Number(pct.toFixed(2));$('expBusinessUseAmountInput').value=e.business_use_amount==null?'':num(e.business_use_amount).toFixed(2);$('expAllocationBasis').value=e.allocation_basis||'';$('expAllocationNotes').value=e.allocation_notes||'';document.querySelectorAll('[data-exp-allocation-method]').forEach(b=>b.classList.toggle('active',b.dataset.expAllocationMethod===(e.allocation_method||'percentage')));renderSplitLines();renderPendingFiles();renderAllocation();switchTab('add');if(isAu())await loadAuTax(e.invoice_date,false)}
  async function duplicateExpense(id){const e=state.expenses.find(x=>x.id===id);if(!e)return;await newExpense();$('expSupplier').value=e.supplier_id||'';$('expReference').value='';$('expInvoiceDate').value=today();$('expDueDate').value=e.due_date?addDays(today(),Math.max(0,Math.round((new Date(e.due_date)-new Date(e.invoice_date))/86400000))):'';$('expDescription').value=e.description||'';$('expCategory').value=e.category_id||'';$('expJob').value=e.job_costing_id||'';$('expAmountType').value=e.amount_type||'inclusive';$('expGstTreatment').value=e.gst_treatment||'gst';resetAuTax();renderAuTax();if($('expAuTaxClass'))$('expAuTaxClass').value=e.au_tax_classification||'';$('expAmount').value=e.amount_type==='exclusive'?num(e.ex_gst):num(e.total_amount);state.split=!!e.is_split;state.splitLines=(e.expense_lines||[]).map(l=>({description:l.description||'',category_id:l.category_id||'',job_costing_id:l.job_costing_id||'',amount:l.total_amount,gst_treatment:l.gst_treatment,gst_rate:l.gst_rate}));$('expSplitArea').hidden=!state.split;const pct=e.business_use_percent==null?100:num(e.business_use_percent);$('expBusinessUseMode').value=pct<99.995?'partial':'full';$('expBusinessUsePercent').value=Number(pct.toFixed(2));$('expBusinessUseAmountInput').value=e.business_use_amount==null?'':num(e.business_use_amount).toFixed(2);$('expAllocationBasis').value=e.allocation_basis||'';$('expAllocationNotes').value=e.allocation_notes||'';document.querySelectorAll('[data-exp-allocation-method]').forEach(b=>b.classList.toggle('active',b.dataset.expAllocationMethod===(e.allocation_method||'percentage')));renderSplitLines();updateAmountDisplay();renderAllocation();toast('Expense copied. Review it before saving.')}
  async function toggleReconcile(id){const e=state.expenses.find(x=>x.id===id);if(!e||isVoidedExpense(e))return;const next=!e.reconciled;if(next){const {error:rerr}=await client().from('expense_reconciliations').insert({expense_id:id,payment_id:null});if(rerr&&!String(rerr.message||'').includes('duplicate'))return toast(rerr.message)}else{const {error:rerr}=await client().from('expense_reconciliations').delete().eq('expense_id',id).is('payment_id',null);if(rerr)return toast(rerr.message)}const {error}=await client().from('expenses').update({reconciled:next,reconciled_at:next?new Date().toISOString():null,reconciled_by:next?(window.SAAS?.state?.user?.id||null):null,updated_by:window.SAAS?.state?.user?.id||null}).eq('id',id);if(error)return toast(error.message);await loadExpenses();renderBills();renderDashboard();toast(next?'Marked reconciled':'Marked unreconciled')}
  async function archiveExpense(id){const e=state.expenses.find(x=>x.id===id);if(isRecordedExpense(e)||isVoidedExpense(e))return recordedExpenseArchiveGuidance();if(!confirm('Archive this expense? Its financial history and documents will be retained.'))return;const {error}=await client().from('expenses').update({archived:true,updated_by:window.SAAS?.state?.user?.id||null}).eq('id',id);if(error)return toast(error.message);await loadExpenses();renderBills();toast('Expense archived')}

  function openPayment(id){const e=state.expenses.find(x=>x.id===id);if(!e||isVoidedExpense(e))return toast('Voided bills cannot receive payments.');$('paymentExpenseId').value=e.id;$('paymentBillLabel').textContent=`${e.expense_number} · ${e.supplier_name} · Balance ${money(supplierCreditAdjustedOutstanding(e))}`;$('paymentDate').value=today();$('paymentAmount').value=supplierCreditAdjustedOutstanding(e).toFixed(2);$('paymentMethod').value='Bank transfer';$('paymentBank').value='';$('paymentReference').value='';$('paymentNotes').value='';$('expensePaymentModal').classList.add('open')}
  async function savePayment(){const id=$('paymentExpenseId').value,e=state.expenses.find(x=>x.id===id),amount=num($('paymentAmount').value);if(isVoidedExpense(e))return toast('Voided bills cannot receive payments.');if(!e||amount<=0)return toast('Enter a payment amount.');if(amount>supplierCreditAdjustedOutstanding(e)+0.005)return toast('Payment cannot exceed the supplier-credit-adjusted outstanding balance.');const {error}=await client().from('expense_payments').insert({expense_id:id,payment_date:$('paymentDate').value||today(),amount,payment_method:$('paymentMethod').value.trim()||null,bank_account:$('paymentBank').value.trim()||null,reference:$('paymentReference').value.trim()||null,notes:$('paymentNotes').value.trim()||null});if(error)return toast(error.message);$('expensePaymentModal').classList.remove('open');await loadExpenses();renderBills();renderPayments();renderDashboard();toast('Payment recorded')}

  async function togglePaymentReconcile(paymentId,expenseId){const e=state.expenses.find(x=>x.id===expenseId),p=e?.expense_payments?.find(x=>x.id===paymentId);if(!p)return;const next=!p.reconciled;if(next){const {error:rerr}=await client().from('expense_reconciliations').insert({expense_id:expenseId,payment_id:paymentId});if(rerr&&!String(rerr.message||'').includes('duplicate'))return toast(rerr.message)}else{const {error:rerr}=await client().from('expense_reconciliations').delete().eq('payment_id',paymentId);if(rerr)return toast(rerr.message)}const {error}=await client().from('expense_payments').update({reconciled:next,reconciled_at:next?new Date().toISOString():null,reconciled_by:next?(window.SAAS?.state?.user?.id||null):null}).eq('id',paymentId);if(error)return toast(error.message);await loadExpenses();renderPayments();toast(next?'Payment reconciled':'Payment unreconciled')}

  function renderSuppliers(){const q=String($('supplierSearch')?.value||'').toLowerCase(),rows=state.suppliers.filter(s=>!q||[s.supplier_name,s.trading_name,s.contact_person,s.email,s.phone].join(' ').toLowerCase().includes(q));$('supplierRows').innerHTML=rows.map(s=>{const exps=state.expenses.filter(e=>e.supplier_id===s.id),spend=exps.reduce((a,e)=>a+num(e.total_amount),0),out=exps.reduce((a,e)=>a+supplierCreditAdjustedOutstanding(e),0);return `<tr><td><strong>${esc(s.supplier_name)}</strong><small>${esc(s.trading_name||'')}</small>${s.archived?'<span class="expense-status status-draft">Archived</span>':''}</td><td>${esc(s.contact_person||'—')}</td><td>${esc(s.phone||s.mobile||'—')}</td><td>${esc(s.email||'—')}</td><td>${money(spend)}</td><td>${money(out)}</td><td><div class="row-actions"><button class="secondary" data-sup-view="${s.id}">View</button><button class="secondary" data-sup-edit="${s.id}">Edit</button><button class="${s.archived?'secondary':'danger'}" data-sup-archive="${s.id}">${s.archived?'Restore':'Archive'}</button></div></td></tr>`}).join('')||'<tr><td colspan="7">No suppliers found.</td></tr>';$('supplierRows').querySelectorAll('[data-sup-view]').forEach(b=>b.onclick=()=>viewSupplier(b.dataset.supView));$('supplierRows').querySelectorAll('[data-sup-edit]').forEach(b=>b.onclick=()=>openSupplierModal(b.dataset.supEdit));$('supplierRows').querySelectorAll('[data-sup-archive]').forEach(b=>b.onclick=()=>toggleSupplierArchive(b.dataset.supArchive))}
