  async function markBatchPaid(id,b){if(!b||!confirm(`Mark ${b.batch_number} as paid? This will record payments against each selected bill.`))return;const items=b.batch_payment_items||[];if(items.some(item=>isVoidedExpense(state.expenses.find(e=>e.id===item.expense_id))))return toast('This batch includes a voided bill and cannot be paid.');for(const item of items){const e=state.expenses.find(x=>x.id===item.expense_id);if(!e)continue;const amount=Math.min(num(item.amount),supplierCreditAdjustedOutstanding(e));if(amount>0){const {error}=await client().from('expense_payments').insert({expense_id:e.id,batch_payment_id:id,payment_date:b.payment_date,amount,payment_method:'Batch payment',bank_account:b.bank_account,reference:b.reference,notes:b.notes});if(error)return toast(error.message)}}const {error}=await client().from('batch_payments').update({status:'paid',paid_at:new Date().toISOString(),updated_by:window.SAAS?.state?.user?.id||null}).eq('id',id);if(error)return toast(error.message);await loadExpenses();renderPayments();renderDashboard();toast('Batch marked paid')}

  function renderDashboard(){const now=new Date(),month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,monthExp=state.expenses.filter(e=>String(e.invoice_date).startsWith(month)&&isActiveExpense(e)),unpaid=state.expenses.filter(e=>isActiveExpense(e)&&supplierCreditAdjustedOutstanding(e)>0.005),overdue=unpaid.filter(e=>e.due_date&&e.due_date<today()),soon=unpaid.filter(e=>e.due_date&&e.due_date>=today()&&e.due_date<=addDays(today(),7)),unrec=state.expenses.filter(e=>!e.reconciled&&isActiveExpense(e));$('expDashMonth').textContent=money(monthExp.reduce((a,e)=>a+num(e.total_amount),0));$('expDashGst').textContent=money(monthExp.reduce((a,e)=>a+num(e.gst_amount),0));$('expDashUnpaid').textContent=money(unpaid.reduce((a,e)=>a+supplierCreditAdjustedOutstanding(e),0));$('expDashUnpaidCount').textContent=`${unpaid.length} bill${unpaid.length===1?'':'s'}`;$('expDashOverdue').textContent=money(overdue.reduce((a,e)=>a+supplierCreditAdjustedOutstanding(e),0));$('expDashOverdueCount').textContent=`${overdue.length} bill${overdue.length===1?'':'s'}`;$('expDashSoon').textContent=money(soon.reduce((a,e)=>a+supplierCreditAdjustedOutstanding(e),0));$('expDashSoonCount').textContent=`${soon.length} bill${soon.length===1?'':'s'}`;$('expDashUnreconciled').textContent=money(unrec.reduce((a,e)=>a+num(e.total_amount),0));$('expDashUnreconciledCount').textContent=`${unrec.length} expense${unrec.length===1?'':'s'}`;$('expenseRecentRows').innerHTML=state.expenses.slice(0,8).map(e=>`<tr><td>${esc(e.invoice_date)}</td><td>${esc(e.supplier_name||'—')}</td><td>${esc(e.expense_number)}</td><td>${money(e.total_amount)}</td><td>${badge(statusOf(e))}</td><td><button class="secondary compact-btn" data-recent-view="${e.id}">View</button></td></tr>`).join('')||'<tr><td colspan="6">No expenses yet.</td></tr>';$('expenseRecentRows').querySelectorAll('[data-recent-view]').forEach(b=>b.onclick=()=>viewExpense(b.dataset.recentView));renderDashboardCharts();runExpenseReport()}
  function renderDashboardCharts(){if(!window.Chart)return;const range=Number($('expenseChartRange')?.value||6),months=[];let d=new Date();d=new Date(d.getFullYear(),d.getMonth()-range+1,1);for(let i=0;i<range;i++){months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);d.setMonth(d.getMonth()+1)}const vals=months.map(m=>state.expenses.filter(e=>String(e.invoice_date).startsWith(m)&&isActiveExpense(e)).reduce((a,e)=>a+num(e.total_amount),0));if(state.charts.month)state.charts.month.destroy();state.charts.month=new Chart($('expenseMonthChart'),{type:'bar',data:{labels:months.map(m=>new Date(m+'-01T12:00:00').toLocaleDateString(undefined,{month:'short',year:'2-digit'})),datasets:[{label:'Expenses',data:vals,backgroundColor:business()?.settings?.primaryColor||'#17324d',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>money(c.raw)}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>money(v)}}}}});const cats=new Map(state.categories.map(c=>[c.id,c.name])),totals={};state.expenses.filter(isActiveExpense).forEach(e=>{if(e.is_split)(e.expense_lines||[]).forEach(l=>totals[cats.get(l.category_id)||'Uncategorised']=(totals[cats.get(l.category_id)||'Uncategorised']||0)+num(l.total_amount));else totals[cats.get(e.category_id)||'Uncategorised']=(totals[cats.get(e.category_id)||'Uncategorised']||0)+num(e.total_amount)});const top=Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,8);if(state.charts.category)state.charts.category.destroy();state.charts.category=new Chart($('expenseCategoryChart'),{type:'doughnut',data:{labels:top.map(x=>x[0]),datasets:[{data:top.map(x=>x[1])}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:c=>`${c.label}: ${money(c.raw)}`}}}}})}

  function payableAgeBucket(e,asOf){
    const balance=supplierCreditAdjustedOutstanding(e);
    if(e.payment_status==='draft'||balance<=0.005)return null;
    const due=e.due_date?new Date(e.due_date+'T12:00:00'):null;
    if(!due||Number.isNaN(due.getTime())||due>asOf)return{key:'current',balance};
    const days=Math.max(1,Math.floor((asOf-due)/86400000));
    if(days<=30)return{key:'d30',balance};
    if(days<=60)return{key:'d60',balance};
    if(days<=90)return{key:'d90',balance};
    return{key:'d91',balance};
  }
  function renderAgedPayables(){
    const body=$('agedPayablesRows'),totalEl=$('agedPayablesTotal'),canvas=$('agedPayablesChart');
    if(!body||!canvas)return;
    const asOf=new Date(),keys=['current','d30','d60','d90','d91'],labels=['Current','1–30 Days','31–60 Days','61–90 Days','91+ Days'];
    const suppliers=new Map(),totals={current:0,d30:0,d60:0,d90:0,d91:0};
    state.expenses.forEach(e=>{
      const bucket=payableAgeBucket(e,asOf);if(!bucket)return;
      const name=String(e.supplier_name||'Unknown supplier').trim()||'Unknown supplier';
      if(!suppliers.has(name))suppliers.set(name,{name,current:0,d30:0,d60:0,d90:0,d91:0,total:0});
      const row=suppliers.get(name);row[bucket.key]+=bucket.balance;row.total+=bucket.balance;totals[bucket.key]+=bucket.balance;
    });
    const list=[...suppliers.values()].sort((a,b)=>b.total-a.total),grand=keys.reduce((n,k)=>n+totals[k],0);
    body.innerHTML=list.length?list.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td>${keys.map(k=>`<td>${money(x[k])}</td>`).join('')}<td><strong>${money(x.total)}</strong></td></tr>`).join(''):'<tr><td colspan="7">No outstanding payables.</td></tr>';
    if(totalEl)totalEl.innerHTML=`<td><strong>TOTALS</strong></td>${keys.map(k=>`<td><strong>${money(totals[k])}</strong></td>`).join('')}<td><strong>${money(grand)}</strong></td>`;
    if(!window.Chart)return;
    if(state.charts.payables)state.charts.payables.destroy();
    const values=keys.map(k=>totals[k]);
    const valueLabels={id:'agedPayablesValueLabels',afterDatasetsDraw(chart){const{ctx}=chart;ctx.save();ctx.font='600 10px Arial, sans-serif';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.fillStyle='#4b5961';chart.getDatasetMeta(0).data.forEach((bar,i)=>{if(values[i]>0)ctx.fillText(money(values[i]),bar.x,bar.y-5)});ctx.restore()}};
    state.charts.payables=new Chart(canvas,{type:'bar',data:{labels,datasets:[{label:'Outstanding amount',data:values,backgroundColor:'#168be3',borderColor:'#168be3',borderWidth:1,borderRadius:4,maxBarThickness:54}]},options:{responsive:true,maintainAspectRatio:false,layout:{padding:{top:28}},plugins:{legend:{display:false},tooltip:{backgroundColor:'#fff',titleColor:'#333',bodyColor:'#333',borderColor:'#cfd8dd',borderWidth:1,displayColors:false,callbacks:{label:c=>money(c.raw)}}},scales:{x:{grid:{display:false},ticks:{color:'#59666e',font:{size:10}}},y:{beginAtZero:true,grid:{color:'#edf1f3'},border:{display:false},ticks:{color:'#7b878e',font:{size:10},callback:v=>money(v)}}}},plugins:[valueLabels]});
  }

  function reportDates(){const preset=$('expenseReportRange')?.value||'this_month',now=new Date(),end=today();let start;if(preset==='this_month')start=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;else if(preset==='last_month'){const a=new Date(now.getFullYear(),now.getMonth()-1,1),b=new Date(now.getFullYear(),now.getMonth(),0);start=`${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,'0')}-01`;return{start,end:`${b.getFullYear()}-${String(b.getMonth()+1).padStart(2,'0')}-${String(b.getDate()).padStart(2,'0')}`}}else if(preset==='3')start=addDays(end,-90);else if(preset==='6')start=addDays(end,-183);else if(preset==='12')start=addDays(end,-365);else return{start:$('expenseReportFrom').value,end:$('expenseReportTo').value};return{start,end}}
  function runExpenseReport(){if(!$('expenseReportRange'))return;const {start,end}=reportDates();$('expenseCustomReportDates').hidden=$('expenseReportRange').value!=='custom';const rows=state.expenses.filter(e=>isActiveExpense(e)&&(!start||e.invoice_date>=start)&&(!end||e.invoice_date<=end));state.reportRows=rows;const total=rows.reduce((a,e)=>a+num(e.total_amount),0),ex=rows.reduce((a,e)=>a+num(e.ex_gst),0),gst=rows.reduce((a,e)=>a+num(e.gst_amount),0),paid=rows.reduce((a,e)=>a+num(e.amount_paid),0),out=rows.reduce((a,e)=>a+supplierCreditAdjustedOutstanding(e),0),over=rows.filter(e=>statusOf(e)==='overdue').reduce((a,e)=>a+supplierCreditAdjustedOutstanding(e),0);$('expReportTotal').textContent=money(total);$('expReportEx').textContent=money(ex);$('expReportGst').textContent=money(gst);$('expReportPaid').textContent=money(paid);$('expReportOutstanding').textContent=money(out);$('expReportOverdue').textContent=money(over);const suppliers={};rows.forEach(e=>suppliers[e.supplier_name||'Unknown']=(suppliers[e.supplier_name||'Unknown']||0)+num(e.total_amount));$('expenseSupplierReportRows').innerHTML=Object.entries(suppliers).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([n,v])=>`<tr><td>${esc(n)}</td><td>${money(v)}</td></tr>`).join('')||'<tr><td colspan="2">No data.</td></tr>';const jobs=new Map(state.jobs.map(j=>[j.id,`${j.costing_number} · ${j.job_description||j.customer_name}`])),jobTotals={};rows.forEach(e=>{if(e.is_split)(e.expense_lines||[]).forEach(l=>{if(l.job_costing_id)jobTotals[jobs.get(l.job_costing_id)||'Job']=(jobTotals[jobs.get(l.job_costing_id)||'Job']||0)+num(l.total_amount)});else if(e.job_costing_id)jobTotals[jobs.get(e.job_costing_id)||'Job']=(jobTotals[jobs.get(e.job_costing_id)||'Job']||0)+num(e.total_amount)});$('expenseJobReportRows').innerHTML=Object.entries(jobTotals).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([n,v])=>`<tr><td>${esc(n)}</td><td>${money(v)}</td></tr>`).join('')||'<tr><td colspan="2">No job-linked expenses.</td></tr>';renderAgedPayables()}
  function exportCsv(){const headers=['Expense #','Date','Supplier','Supplier Reference','Description','Original Ex GST','Original GST','Original Total','Business Use %','Business Ex GST','Business GST','Business Total','Private Amount','Allocation Basis','Amount Paid','Balance','Payment Status','Reconciled','Currency'],rows=state.reportRows.map(e=>[e.expense_number,e.invoice_date,e.supplier_name||'',e.supplier_reference||'',e.description||'',e.ex_gst,e.gst_amount,e.total_amount,e.business_use_percent??100,e.business_ex_gst??e.ex_gst,e.business_gst_amount??e.gst_amount,e.business_use_amount??e.total_amount,e.private_use_amount??0,e.allocation_basis||'',e.amount_paid,supplierCreditAdjustedOutstanding(e),statusOf(e),e.reconciled?'Yes':'No',e.currency]);const csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`expenses-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}

