  function bind(){if(state.init)return;state.init=true;injectModals();document.querySelectorAll('[data-exp-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.expTab));document.querySelectorAll('[data-exp-add]').forEach(b=>b.onclick=newExpense);$('expSupplier').onchange=supplierChanged;$('expCreateSupplier').onclick=()=>openSupplierModal(null,true);$('expCreateCategory').onclick=()=>switchTab('categories');if($('backToExpenseAdd'))$('backToExpenseAdd').onclick=()=>switchTab('add');$('expSplitToggle').onclick=toggleSplit;$('expAddSplit').onclick=()=>{state.splitLines.push({description:'',category_id:'',job_costing_id:'',amount:0,gst_treatment:$('expGstTreatment').value||'gst',gst_rate:gstRate()});renderSplitLines()};['expAmount','expAmountType','expGstTreatment','expGstAmount'].forEach(id=>$(id).addEventListener('input',updateAmountDisplay));$('expGstOverride').onchange=()=>{$('expGstAmount').readOnly=!$('expGstOverride').checked;updateAmountDisplay()};if($('expAuTaxClass'))$('expAuTaxClass').onchange=()=>{const c=$('expAuTaxClass').value;if(c)$('expGstTreatment').value=c==='gst_taxable'?'gst':'no_gst';updateAmountDisplay()};$('expBusinessUseMode').onchange=renderAllocation;$('expBusinessUsePercent').oninput=renderAllocation;$('expBusinessUseAmountInput').oninput=renderAllocation;$('expAllocationBasis').onchange=renderAllocation;document.querySelectorAll('[data-exp-allocation-method]').forEach(b=>b.onclick=()=>{const c=state.split?{total:num($('expTotalCalculated').value),ex:num($('expExGst').value),gst:num($('expGstAmount').value)}:currentAmount(),before=allocationFor(c);document.querySelectorAll('[data-exp-allocation-method]').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.expAllocationMethod==='business_amount')$('expBusinessUseAmountInput').value=before.business.toFixed(2);else $('expBusinessUsePercent').value=Number(before.pct.toFixed(2));renderAllocation()});$('expInvoiceDate').onchange=async()=>{if(isAu())await loadAuTax($('expInvoiceDate').value,!state.editingId&&!$('expAuTaxClass').value);const s=state.suppliers.find(x=>x.id===$('expSupplier').value);if(s?.payment_terms_days)$('expDueDate').value=addDays($('expInvoiceDate').value,s.payment_terms_days)};$('expSave').onclick=saveExpense;$('expCancel').onclick=()=>switchTab('bills');$('expTakePhoto').onclick=()=>$('expCameraFile').click();$('expUploadDoc').onclick=()=>$('expDocumentFile').click();if($('expAiRescan'))$('expAiRescan').onclick=()=>scanExpenseFile();['expCameraFile','expDocumentFile'].forEach(id=>$(id).onchange=e=>{pickFiles(e.target.files);e.target.value=''});['expSupplier','expReference','expInvoiceDate','expDueDate','expDescription','expCategory','expAmountType','expGstTreatment','expAuTaxClass','expAmount','expGstOverride','expGstAmount','expPaymentStatus'].forEach(id=>{const el=$(id);if(el){el.addEventListener('input',markTouched);el.addEventListener('change',markTouched)}});
    if($('expenseListRange')){$('expenseListRange').onchange=()=>{syncExpenseListDates();renderBills()};syncExpenseListDates()}
    if($('expenseSearch'))$('expenseSearch').oninput=renderBills;if($('expenseFrom'))$('expenseFrom').onchange=()=>{if($('expenseListRange'))$('expenseListRange').value='custom';renderBills()};if($('expenseTo'))$('expenseTo').onchange=()=>{if($('expenseListRange'))$('expenseListRange').value='custom';renderBills()};if($('expenseResetFilters'))$('expenseResetFilters').onclick=()=>{$('expenseSearch').value='';$('expenseListRange').value='this_month';syncExpenseListDates();renderBills()};if($('expenseBillsExportCsv'))$('expenseBillsExportCsv').onclick=exportBillsCsv;
    $('supplierSearch').oninput=renderSuppliers;$('addSupplierBtn').onclick=()=>openSupplierModal();$('addExpenseCategory').onclick=()=>addCategory(false);$('createBatchPayment').onclick=openBatch;if($('expenseChartRange'))$('expenseChartRange').onchange=renderDashboardCharts;if($('expenseReportRange'))$('expenseReportRange').onchange=runExpenseReport;if($('expenseReportFrom'))$('expenseReportFrom').onchange=runExpenseReport;if($('expenseReportTo'))$('expenseReportTo').onchange=runExpenseReport;if($('expenseExportCsv'))$('expenseExportCsv').onclick=exportCsv;}

