  window.Expenses={init,onShow,switchTab,showReport:async()=>{if(!state.init)await init();else{await loadReferenceData();await loadExpenses()}renderDashboard()},refresh:async()=>{await loadReferenceData();await loadExpenses();switchTab(state.activeTab)},openAddForJob:async(jobId)=>{if(!state.init)await init();else await loadReferenceData();await newExpense();if($('expJob'))$('expJob').value=jobId||''}};
